def top_p_filter(probs, p):
    ordered = sorted(probs.items(), key=lambda kv: (-kv[1], kv[0]))
    kept, cum = [], 0.0
    for tok, pr in ordered:
        kept.append((tok, pr))
        cum += pr
        if cum >= p - 1e-12:
            break
    total = sum(pr for _, pr in kept)
    return {tok: pr / total for tok, pr in kept}

