from collections import Counter, defaultdict

def greedy_generate(corpus, start, max_tokens):
    toks = corpus.split()
    follows = defaultdict(Counter)
    for a, b in zip(toks, toks[1:]):
        follows[a][b] += 1
    out = [start]
    for _ in range(max_tokens):
        options = follows.get(out[-1])
        if not options:
            break
        nxt = sorted(options.items(), key=lambda kv: (-kv[1], kv[0]))[0][0]
        out.append(nxt)
        if nxt == '.':
            break
    return ' '.join(out)
